export default function Page() {
  const [country, setCountry] = React.useState('All countries');
  const [search, setSearch] = React.useState('');
  const countries = ['All countries', 'CZE', 'POL', 'DEU', 'AUT'];

  return (
    <div className="w-full bg-white p-4 border-b border-gray-200">
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3 max-w-3xl mx-auto">
        <div className="flex flex-col">
          <label htmlFor="country-select" className="text-xs font-medium text-gray-500 mb-1">
            Country
          </label>
          <select
            id="country-select"
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            className="border border-gray-300 rounded-md px-3 py-2 text-sm text-gray-700 bg-white focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 min-w-[160px]"
          >
            {countries.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
        </div>

        <div className="flex flex-col flex-1">
          <label htmlFor="race-search" className="text-xs font-medium text-gray-500 mb-1">
            Search races
          </label>
          <input
            id="race-search"
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search races by name..."
            className="border border-gray-300 rounded-md px-3 py-2 text-sm text-gray-700 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 w-full"
          />
        </div>
      </div>
    </div>
  );
}
